const EX=[{"id": "Barbell_Squat", "n": "Barbell Squat", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings", "lower back"], "ins": ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Barbell_Squat_0.jpg", "img/Barbell_Squat_1.jpg"]}, {"id": "Barbell_Deadlift", "n": "Barbell Deadlift", "lv": "intermediate", "eq": "barbell", "cat": "strength", "pm": ["lower back"], "sm": ["calves", "forearms", "glutes", "hamstrings", "lats", "middle back", "quadriceps", "traps"], "ins": ["Stand in front of a loaded barbell.", "While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.", "While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.", "Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.", "Perform the amount of repetitions prescribed in the program."], "im": ["img/Barbell_Deadlift_0.jpg", "img/Barbell_Deadlift_1.jpg"]}, {"id": "Romanian_Deadlift", "n": "Romanian Deadlift", "lv": "intermediate", "eq": "barbell", "cat": "strength", "pm": ["hamstrings"], "sm": ["calves", "glutes", "lower back"], "ins": ["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.", "Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.", "Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.", "Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.", "Repeat for the recommended amount of repetitions."], "im": ["img/Romanian_Deadlift_0.jpg", "img/Romanian_Deadlift_1.jpg"]}, {"id": "Barbell_Bench_Press_-_Medium_Grip", "n": "Barbell Bench Press - Medium Grip", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."], "im": ["img/Barbell_Bench_Press_-_Medium_Grip_0.jpg", "img/Barbell_Bench_Press_-_Medium_Grip_1.jpg"]}, {"id": "Incline_Dumbbell_Press", "n": "Incline Dumbbell Press", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.", "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.", "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."], "im": ["img/Incline_Dumbbell_Press_0.jpg", "img/Incline_Dumbbell_Press_1.jpg"]}, {"id": "Dumbbell_Bench_Press", "n": "Dumbbell Bench Press", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.", "Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions of your training program."], "im": ["img/Dumbbell_Bench_Press_0.jpg", "img/Dumbbell_Bench_Press_1.jpg"]}, {"id": "Pushups", "n": "Pushups", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."], "im": ["img/Pushups_0.jpg", "img/Pushups_1.jpg"]}, {"id": "Chin-Up", "n": "Chin-Up", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["lats"], "sm": ["biceps", "forearms", "middle back"], "ins": ["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.", "As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."], "im": ["img/Chin-Up_0.jpg", "img/Chin-Up_1.jpg"]}, {"id": "Wide-Grip_Lat_Pulldown", "n": "Wide-Grip Lat Pulldown", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["lats"], "sm": ["biceps", "middle back", "shoulders"], "ins": ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."], "im": ["img/Wide-Grip_Lat_Pulldown_0.jpg", "img/Wide-Grip_Lat_Pulldown_1.jpg"]}, {"id": "Seated_Cable_Rows", "n": "Seated Cable Rows", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["middle back"], "sm": ["biceps", "lats", "shoulders"], "ins": ["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Seated_Cable_Rows_0.jpg", "img/Seated_Cable_Rows_1.jpg"]}, {"id": "Bent_Over_Barbell_Row", "n": "Bent Over Barbell Row", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["middle back"], "sm": ["biceps", "lats", "shoulders"], "ins": ["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.", "Then inhale and slowly lower the barbell back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Bent_Over_Barbell_Row_0.jpg", "img/Bent_Over_Barbell_Row_1.jpg"]}, {"id": "One-Arm_Dumbbell_Row", "n": "One-Arm Dumbbell Row", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["middle back"], "sm": ["biceps", "lats", "shoulders"], "ins": ["Choose a flat bench and place a dumbbell on each side of it.", "Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.", "Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.", "Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.", "Lower the resistance straight down to the starting position. Breathe in as you perform this step.", "Repeat the movement for the specified amount of repetitions.", "Switch sides and repeat again with the other arm."], "im": ["img/One-Arm_Dumbbell_Row_0.jpg", "img/One-Arm_Dumbbell_Row_1.jpg"]}, {"id": "Barbell_Shoulder_Press", "n": "Barbell Shoulder Press", "lv": "intermediate", "eq": "barbell", "cat": "strength", "pm": ["shoulders"], "sm": ["chest", "triceps"], "ins": ["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).", "Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the shoulders slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Barbell_Shoulder_Press_0.jpg", "img/Barbell_Shoulder_Press_1.jpg"]}, {"id": "Dumbbell_Shoulder_Press", "n": "Dumbbell Shoulder Press", "lv": "intermediate", "eq": "dumbbell", "cat": "strength", "pm": ["shoulders"], "sm": ["triceps"], "ins": ["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.", "Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.", "Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.", "Now, exhale and push the dumbbells upward until they touch at the top.", "Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."], "im": ["img/Dumbbell_Shoulder_Press_0.jpg", "img/Dumbbell_Shoulder_Press_1.jpg"]}, {"id": "Side_Lateral_Raise", "n": "Side Lateral Raise", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["shoulders"], "sm": [], "ins": ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.", "While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbells back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Side_Lateral_Raise_0.jpg", "img/Side_Lateral_Raise_1.jpg"]}, {"id": "Front_Dumbbell_Raise", "n": "Front Dumbbell Raise", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["shoulders"], "sm": [], "ins": ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.", "While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.", "Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.", "Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."], "im": ["img/Front_Dumbbell_Raise_0.jpg", "img/Front_Dumbbell_Raise_1.jpg"]}, {"id": "Face_Pull", "n": "Face Pull", "lv": "intermediate", "eq": "cable", "cat": "strength", "pm": ["shoulders"], "sm": ["middle back"], "ins": ["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."], "im": ["img/Face_Pull_0.jpg", "img/Face_Pull_1.jpg"]}, {"id": "Barbell_Curl", "n": "Barbell Curl", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["biceps"], "sm": ["forearms"], "ins": ["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.", "While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.", "Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.", "Slowly begin to bring the bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Barbell_Curl_0.jpg", "img/Barbell_Curl_1.jpg"]}, {"id": "Dumbbell_Bicep_Curl", "n": "Dumbbell Bicep Curl", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["biceps"], "sm": ["forearms"], "ins": ["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Dumbbell_Bicep_Curl_0.jpg", "img/Dumbbell_Bicep_Curl_1.jpg"]}, {"id": "Hammer_Curls", "n": "Hammer Curls", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["biceps"], "sm": [], "ins": ["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.", "The palms of the hands should be facing your torso. This will be your starting position.", "Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.", "After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Hammer_Curls_0.jpg", "img/Hammer_Curls_1.jpg"]}, {"id": "Triceps_Pushdown", "n": "Triceps Pushdown", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["triceps"], "sm": [], "ins": ["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.", "Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."], "im": ["img/Triceps_Pushdown_0.jpg", "img/Triceps_Pushdown_1.jpg"]}, {"id": "Tricep_Dumbbell_Kickback", "n": "Tricep Dumbbell Kickback", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["triceps"], "sm": [], "ins": ["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.", "Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.", "After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.", "Repeat the movement for the prescribed amount of repetitions."], "im": ["img/Tricep_Dumbbell_Kickback_0.jpg", "img/Tricep_Dumbbell_Kickback_1.jpg"]}, {"id": "Lying_Triceps_Press", "n": "Lying Triceps Press", "lv": "intermediate", "eq": "e-z curl bar", "cat": "strength", "pm": ["triceps"], "sm": [], "ins": ["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.", "Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.", "As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.", "At that point, use the triceps to bring the weight back up to the starting position as you breathe out.", "Repeat for the recommended amount of repetitions."], "im": ["img/Lying_Triceps_Press_0.jpg", "img/Lying_Triceps_Press_1.jpg"]}, {"id": "Dips_-_Triceps_Version", "n": "Dips - Triceps Version", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["triceps"], "sm": ["chest", "shoulders"], "ins": ["To get into the starting position, hold your body at arm's length with your arms nearly locked above the bars.", "Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.", "Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.", "Repeat the movement for the prescribed amount of repetitions."], "im": ["img/Dips_-_Triceps_Version_0.jpg", "img/Dips_-_Triceps_Version_1.jpg"]}, {"id": "Leg_Press", "n": "Leg Press", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."], "im": ["img/Leg_Press_0.jpg", "img/Leg_Press_1.jpg"]}, {"id": "Leg_Extensions", "n": "Leg Extensions", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["quadriceps"], "sm": [], "ins": ["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.", "Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.", "Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.", "Repeat for the recommended amount of times."], "im": ["img/Leg_Extensions_0.jpg", "img/Leg_Extensions_1.jpg"]}, {"id": "Lying_Leg_Curls", "n": "Lying Leg Curls", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["hamstrings"], "sm": [], "ins": ["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."], "im": ["img/Lying_Leg_Curls_0.jpg", "img/Lying_Leg_Curls_1.jpg"]}, {"id": "Standing_Calf_Raises", "n": "Standing Calf Raises", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["calves"], "sm": [], "ins": ["Adjust the padded lever of the calf raise machine to fit your height.", "Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."], "im": ["img/Standing_Calf_Raises_0.jpg", "img/Standing_Calf_Raises_1.jpg"]}, {"id": "Seated_Calf_Raise", "n": "Seated Calf Raise", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["calves"], "sm": [], "ins": ["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.", "Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.", "Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.", "Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.", "Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.", "Repeat for the recommended amount of repetitions."], "im": ["img/Seated_Calf_Raise_0.jpg", "img/Seated_Calf_Raise_1.jpg"]}, {"id": "Barbell_Lunge", "n": "Barbell Lunge", "lv": "intermediate", "eq": "barbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>", "Using mainly the heel of your foot, push up and go back to the starting position as you exhale.", "Repeat the movement for the recommended amount of repetitions and then perform with the left leg."], "im": ["img/Barbell_Lunge_0.jpg", "img/Barbell_Lunge_1.jpg"]}, {"id": "Dumbbell_Lunges", "n": "Dumbbell Lunges", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.", "Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.", "Using mainly the heel of your foot, push up and go back to the starting position as you exhale.", "Repeat the movement for the recommended amount of repetitions and then perform with the left leg."], "im": ["img/Dumbbell_Lunges_0.jpg", "img/Dumbbell_Lunges_1.jpg"]}, {"id": "Goblet_Squat", "n": "Goblet Squat", "lv": "beginner", "eq": "kettlebells", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings", "shoulders"], "ins": ["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.", "Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.", "At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."], "im": ["img/Goblet_Squat_0.jpg", "img/Goblet_Squat_1.jpg"]}, {"id": "Bodyweight_Squat", "n": "Bodyweight Squat", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["quadriceps"], "sm": ["glutes", "hamstrings"], "ins": ["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.", "Begin the movement by flexing your knees and hips, sitting back with your hips.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."], "im": ["img/Bodyweight_Squat_0.jpg", "img/Bodyweight_Squat_1.jpg"]}, {"id": "Barbell_Hip_Thrust", "n": "Barbell Hip Thrust", "lv": "intermediate", "eq": "barbell", "cat": "powerlifting", "pm": ["glutes"], "sm": ["calves", "hamstrings"], "ins": ["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."], "im": ["img/Barbell_Hip_Thrust_0.jpg", "img/Barbell_Hip_Thrust_1.jpg"]}, {"id": "Barbell_Glute_Bridge", "n": "Barbell Glute Bridge", "lv": "intermediate", "eq": "barbell", "cat": "powerlifting", "pm": ["glutes"], "sm": ["calves", "hamstrings"], "ins": ["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.", "Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.", "Extend as far as possible, then reverse the motion to return to the starting position."], "im": ["img/Barbell_Glute_Bridge_0.jpg", "img/Barbell_Glute_Bridge_1.jpg"]}, {"id": "Plank", "n": "Plank", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."], "im": ["img/Plank_0.jpg", "img/Plank_1.jpg"]}, {"id": "Crunches", "n": "Crunches", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.", "Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.", "While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.", "Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.", "After the one second contraction, begin to come down slowly again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Crunches_0.jpg", "img/Crunches_1.jpg"]}, {"id": "Russian_Twist", "n": "Russian Twist", "lv": "intermediate", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": ["lower back"], "ins": ["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.", "Twist your torso to the right side until your arms are parallel with the floor while breathing out.", "Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.", "Repeat for the recommended amount of repetitions."], "im": ["img/Russian_Twist_0.jpg", "img/Russian_Twist_1.jpg"]}, {"id": "Hanging_Leg_Raise", "n": "Hanging Leg Raise", "lv": "expert", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.", "Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.", "Go back slowly to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Hanging_Leg_Raise_0.jpg", "img/Hanging_Leg_Raise_1.jpg"]}, {"id": "Cable_Crunch", "n": "Cable Crunch", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Kneel below a high pulley that contains a rope attachment.", "Grasp cable rope attachment and lower the rope until your hands are placed next to your face.", "Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.", "With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.", "Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.", "Repeat for the recommended amount of repetitions."], "im": ["img/Cable_Crunch_0.jpg", "img/Cable_Crunch_1.jpg"]}, {"id": "Mountain_Climbers", "n": "Mountain Climbers", "lv": "beginner", "eq": "body only", "cat": "plyometrics", "pm": ["quadriceps"], "sm": ["chest", "hamstrings", "shoulders"], "ins": ["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.", "Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."], "im": ["img/Mountain_Climbers_0.jpg", "img/Mountain_Climbers_1.jpg"]}, {"id": "Dumbbell_Flyes", "n": "Dumbbell Flyes", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["chest"], "sm": [], "ins": ["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.", "Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."], "im": ["img/Dumbbell_Flyes_0.jpg", "img/Dumbbell_Flyes_1.jpg"]}, {"id": "Cable_Crossover", "n": "Cable Crossover", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["chest"], "sm": ["shoulders"], "ins": ["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.", "Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."], "im": ["img/Cable_Crossover_0.jpg", "img/Cable_Crossover_1.jpg"]}, {"id": "Butterfly", "n": "Butterfly", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["chest"], "sm": [], "ins": ["Sit on the machine with your back flat on the pad.", "Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.", "Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.", "Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.", "Repeat for the recommended amount of repetitions."], "im": ["img/Butterfly_0.jpg", "img/Butterfly_1.jpg"]}, {"id": "Barbell_Shrug", "n": "Barbell Shrug", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["traps"], "sm": [], "ins": ["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.", "Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Barbell_Shrug_0.jpg", "img/Barbell_Shrug_1.jpg"]}, {"id": "Dumbbell_Shrug", "n": "Dumbbell Shrug", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["traps"], "sm": [], "ins": ["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.", "Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.", "Lower the dumbbells back to the original position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Dumbbell_Shrug_0.jpg", "img/Dumbbell_Shrug_1.jpg"]}, {"id": "Hyperextensions_Back_Extensions", "n": "Hyperextensions (Back Extensions)", "lv": "beginner", "eq": "other", "cat": "strength", "pm": ["lower back"], "sm": ["glutes", "hamstrings"], "ins": ["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.", "Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.", "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.", "Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.", "Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.", "Repeat for the recommended amount of repetitions."], "im": ["img/Hyperextensions_Back_Extensions_0.jpg", "img/Hyperextensions_Back_Extensions_1.jpg"]}, {"id": "Good_Morning", "n": "Good Morning", "lv": "intermediate", "eq": "barbell", "cat": "powerlifting", "pm": ["hamstrings"], "sm": ["abdominals", "glutes", "lower back"], "ins": ["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.", "Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.", "Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."], "im": ["img/Good_Morning_0.jpg", "img/Good_Morning_1.jpg"]}, {"id": "One-Arm_Kettlebell_Swings", "n": "One-Arm Kettlebell Swings", "lv": "intermediate", "eq": "kettlebells", "cat": "strength", "pm": ["hamstrings"], "sm": ["calves", "glutes", "lower back", "shoulders"], "ins": [], "im": ["img/One-Arm_Kettlebell_Swings_0.jpg", "img/One-Arm_Kettlebell_Swings_1.jpg"]}, {"id": "Front_Barbell_Squat", "n": "Front Barbell Squat", "lv": "expert", "eq": "barbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.", "Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Front_Barbell_Squat_0.jpg", "img/Front_Barbell_Squat_1.jpg"]}, {"id": "Hack_Squat", "n": "Hack Squat", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.", "Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).", "Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Hack_Squat_0.jpg", "img/Hack_Squat_1.jpg"]}, {"id": "Smith_Machine_Squat", "n": "Smith Machine Squat", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings", "lower back"], "ins": ["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Smith_Machine_Squat_0.jpg", "img/Smith_Machine_Squat_1.jpg"]}, {"id": "Step-up_with_Knee_Raise", "n": "Step-up with Knee Raise", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["glutes"], "sm": ["hamstrings", "quadriceps"], "ins": ["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.", "Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.", "Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."], "im": ["img/Step-up_with_Knee_Raise_0.jpg", "img/Step-up_with_Knee_Raise_1.jpg"]}, {"id": "Arnold_Dumbbell_Press", "n": "Arnold Dumbbell Press", "lv": "intermediate", "eq": "dumbbell", "cat": "strength", "pm": ["shoulders"], "sm": ["triceps"], "ins": ["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.", "Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.", "Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.", "After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."], "im": ["img/Arnold_Dumbbell_Press_0.jpg", "img/Arnold_Dumbbell_Press_1.jpg"]}, {"id": "Reverse_Flyes", "n": "Reverse Flyes", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["shoulders"], "sm": [], "ins": ["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).", "Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.", "Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.", "The arms should be elevated until they are parallel to the floor.", "Feel the contraction and slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."], "im": ["img/Reverse_Flyes_0.jpg", "img/Reverse_Flyes_1.jpg"]}, {"id": "Cable_Hammer_Curls_-_Rope_Attachment", "n": "Cable Hammer Curls - Rope Attachment", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["biceps"], "sm": [], "ins": ["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.", "Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.", "Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.", "Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.", "After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Cable_Hammer_Curls_-_Rope_Attachment_0.jpg", "img/Cable_Hammer_Curls_-_Rope_Attachment_1.jpg"]}, {"id": "Preacher_Curl", "n": "Preacher Curl", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["biceps"], "sm": [], "ins": ["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.", "With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.", "As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.", "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.", "Repeat for the recommended amount of repetitions."], "im": ["img/Preacher_Curl_0.jpg", "img/Preacher_Curl_1.jpg"]}, {"id": "Concentration_Curls", "n": "Concentration Curls", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["biceps"], "sm": ["forearms"], "ins": ["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.", "Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.", "While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.", "Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.", "Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."], "im": ["img/Concentration_Curls_0.jpg", "img/Concentration_Curls_1.jpg"]}, {"id": "Close-Grip_Barbell_Bench_Press", "n": "Close-Grip Barbell Bench Press", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["triceps"], "sm": ["chest", "shoulders"], "ins": ["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."], "im": ["img/Close-Grip_Barbell_Bench_Press_0.jpg", "img/Close-Grip_Barbell_Bench_Press_1.jpg"]}, {"id": "Incline_Push-Up", "n": "Incline Push-Up", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.", "Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.", "Push body up until arms are extended. Repeat."], "im": ["img/Incline_Push-Up_0.jpg", "img/Incline_Push-Up_1.jpg"]}, {"id": "Decline_Push-Up", "n": "Decline Push-Up", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."], "im": ["img/Decline_Push-Up_0.jpg", "img/Decline_Push-Up_1.jpg"]}, {"id": "Flutter_Kicks", "n": "Flutter Kicks", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["glutes"], "sm": ["hamstrings"], "ins": ["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.", "Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.", "Start the movement by lifting the left leg higher than the right leg.", "Then lower the left leg as you lift the right leg.", "Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."], "im": ["img/Flutter_Kicks_0.jpg", "img/Flutter_Kicks_1.jpg"]}, {"id": "Side_Bridge", "n": "Side Bridge", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": ["shoulders"], "ins": [], "im": ["img/Side_Bridge_0.jpg", "img/Side_Bridge_1.jpg"]}, {"id": "Superman", "n": "Superman", "lv": "beginner", "eq": "body only", "cat": "stretching", "pm": ["lower back"], "sm": ["glutes", "hamstrings"], "ins": ["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.", "Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.", "Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions prescribed in your program."], "im": ["img/Superman_0.jpg", "img/Superman_1.jpg"]}, {"id": "Walking_Treadmill", "n": "Walking, Treadmill", "lv": "beginner", "eq": "machine", "cat": "cardio", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.", "Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn't burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."], "im": ["img/Walking_Treadmill_0.jpg", "img/Walking_Treadmill_1.jpg"]}, {"id": "Jogging_Treadmill", "n": "Jogging, Treadmill", "lv": "beginner", "eq": "machine", "cat": "cardio", "pm": ["quadriceps"], "sm": ["glutes", "hamstrings"], "ins": ["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.", "Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."], "im": ["img/Jogging_Treadmill_0.jpg", "img/Jogging_Treadmill_1.jpg"]}, {"id": "Rope_Jumping", "n": "Rope Jumping", "lv": "intermediate", "eq": "other", "cat": "cardio", "pm": ["quadriceps"], "sm": ["calves", "hamstrings"], "ins": ["Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.", "Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running."], "im": ["img/Rope_Jumping_0.jpg", "img/Rope_Jumping_1.jpg"]}, {"id": "Rowing_Stationary", "n": "Rowing, Stationary", "lv": "intermediate", "eq": "machine", "cat": "cardio", "pm": ["quadriceps"], "sm": ["biceps", "calves", "glutes", "hamstrings", "lower back", "middle back"], "ins": ["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.", "There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.", "The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."], "im": ["img/Rowing_Stationary_0.jpg", "img/Rowing_Stationary_1.jpg"]}, {"id": "Stairmaster", "n": "Stairmaster", "lv": "intermediate", "eq": "machine", "cat": "cardio", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.", "Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don't fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.", "Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."], "im": ["img/Stairmaster_0.jpg", "img/Stairmaster_1.jpg"]}, {"id": "Seated_Leg_Curl", "n": "Seated Leg Curl", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["hamstrings"], "sm": [], "ins": ["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.", "Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.", "As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Seated_Leg_Curl_0.jpg", "img/Seated_Leg_Curl_1.jpg"]}, {"id": "Leverage_Chest_Press", "n": "Leverage Chest Press", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.", "Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "im": ["img/Leverage_Chest_Press_0.jpg", "img/Leverage_Chest_Press_1.jpg"]}, {"id": "Wide-Grip_Rear_Pull-Up", "n": "Wide-Grip Rear Pull-Up", "lv": "intermediate", "eq": "body only", "cat": "strength", "pm": ["lats"], "sm": ["biceps", "middle back", "shoulders"], "ins": ["Grab the pull-up bar with the palms facing forward using a wide grip.", "As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.", "Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."], "im": ["img/Wide-Grip_Rear_Pull-Up_0.jpg", "img/Wide-Grip_Rear_Pull-Up_1.jpg"]}, {"id": "Straight-Arm_Pulldown", "n": "Straight-Arm Pulldown", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["lats"], "sm": [], "ins": ["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.", "Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.", "While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.", "While keeping the arms straight, go back to the starting position while breathing in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Straight-Arm_Pulldown_0.jpg", "img/Straight-Arm_Pulldown_1.jpg"]}, {"id": "Cable_Shoulder_Press", "n": "Cable Shoulder Press", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["shoulders"], "sm": ["triceps"], "ins": ["Move the cables to the bottom of the towers and select an appropriate weight.", "Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.", "Keeping your head and chest up, extend through the elbow to press the handles directly over head.", "After pausing at the top, return to the starting position and repeat."], "im": ["img/Cable_Shoulder_Press_0.jpg", "img/Cable_Shoulder_Press_1.jpg"]}, {"id": "Machine_Shoulder_Military_Press", "n": "Machine Shoulder (Military) Press", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["shoulders"], "sm": ["triceps"], "ins": ["Sit down on the Shoulder Press Machine and select the weight.", "Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.", "Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.", "Lower the handles slowly back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Machine_Shoulder_Military_Press_0.jpg", "img/Machine_Shoulder_Military_Press_1.jpg"]}, {"id": "Calf_Press_On_The_Leg_Press_Machine", "n": "Calf Press On The Leg Press Machine", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["calves"], "sm": [], "ins": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."], "im": ["img/Calf_Press_On_The_Leg_Press_Machine_0.jpg", "img/Calf_Press_On_The_Leg_Press_Machine_1.jpg"]}, {"id": "Sumo_Deadlift", "n": "Sumo Deadlift", "lv": "intermediate", "eq": "barbell", "cat": "powerlifting", "pm": ["hamstrings"], "sm": ["adductors", "forearms", "glutes", "lower back", "middle back", "quadriceps", "traps"], "ins": ["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.", "Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.", "As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.", "Return the weight to the ground by bending at the hips and controlling the weight on the way down."], "im": ["img/Sumo_Deadlift_0.jpg", "img/Sumo_Deadlift_1.jpg"]}, {"id": "Trap_Bar_Deadlift", "n": "Trap Bar Deadlift", "lv": "beginner", "eq": "other", "cat": "strength", "pm": ["quadriceps"], "sm": ["glutes", "hamstrings"], "ins": ["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.", "Lower your hips, look forward with your head and keep your chest up.", "Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.", "At the completion of the movement, lower the weight back to the ground under control."], "im": ["img/Trap_Bar_Deadlift_0.jpg", "img/Trap_Bar_Deadlift_1.jpg"]}, {"id": "Dumbbell_Squat", "n": "Dumbbell Squat", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings", "lower back"], "ins": ["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).", "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.", "Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Dumbbell_Squat_0.jpg", "img/Dumbbell_Squat_1.jpg"]}, {"id": "Single_Leg_Glute_Bridge", "n": "Single Leg Glute Bridge", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["glutes"], "sm": ["hamstrings"], "ins": ["Lay on the floor with your feet flat and knees bent.", "Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.", "Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.", "Extend as far as possible, pause and then return to the starting position."], "im": ["img/Single_Leg_Glute_Bridge_0.jpg", "img/Single_Leg_Glute_Bridge_1.jpg"]}, {"id": "Dumbbell_Step_Ups", "n": "Dumbbell Step Ups", "lv": "intermediate", "eq": "dumbbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).", "Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.", "Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.", "Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."], "im": ["img/Dumbbell_Step_Ups_0.jpg", "img/Dumbbell_Step_Ups_1.jpg"]}, {"id": "Inverted_Row", "n": "Inverted Row", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["middle back"], "sm": ["lats"], "ins": ["Position a bar in a rack to about waist height. You can also use a smith machine.", "Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.", "Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.", "Pause at the top of the motion, and return yourself to the start position.", "Repeat for the desired number of repetitions."], "im": ["img/Inverted_Row_0.jpg", "img/Inverted_Row_1.jpg"]}, {"id": "Bench_Dips", "n": "Bench Dips", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["triceps"], "sm": ["chest", "shoulders"], "ins": ["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.", "Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.", "Using your triceps to bring your torso up again, lift yourself back to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Bench_Dips_0.jpg", "img/Bench_Dips_1.jpg"]}, {"id": "Close-Grip_Front_Lat_Pulldown", "n": "Close-Grip Front Lat Pulldown", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["lats"], "sm": ["biceps", "middle back", "shoulders"], "ins": ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.", "After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "6. Repeat this motion for the prescribed amount of repetitions."], "im": ["img/Close-Grip_Front_Lat_Pulldown_0.jpg", "img/Close-Grip_Front_Lat_Pulldown_1.jpg"]}, {"id": "Cable_Preacher_Curl", "n": "Cable Preacher Curl", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["biceps"], "sm": ["forearms"], "ins": ["Place a preacher bench about 2 feet in front of a pulley machine.", "Attach a straight bar to the low pulley.", "Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.", "Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.", "Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.", "Now slowly lower the weight to the starting position.", "Repeat for the recommended amount of repetitions."], "im": ["img/Cable_Preacher_Curl_0.jpg", "img/Cable_Preacher_Curl_1.jpg"]}, {"id": "Incline_Dumbbell_Curl", "n": "Incline Dumbbell Curl", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["biceps"], "sm": [], "ins": ["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.", "Slowly begin to bring the dumbbells back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "im": ["img/Incline_Dumbbell_Curl_0.jpg", "img/Incline_Dumbbell_Curl_1.jpg"]}, {"id": "Alternate_Incline_Dumbbell_Curl", "n": "Alternate Incline Dumbbell Curl", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["biceps"], "sm": ["forearms"], "ins": ["Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.", "While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.", "Slowly begin to bring the dumbbell back to starting position as your breathe in.", "Repeat the movement with the left hand. This equals one repetition.", "Continue alternating in this manner for the recommended amount of repetitions."], "im": ["img/Alternate_Incline_Dumbbell_Curl_0.jpg", "img/Alternate_Incline_Dumbbell_Curl_1.jpg"]}, {"id": "Dumbbell_One-Arm_Triceps_Extension", "n": "Dumbbell One-Arm Triceps Extension", "lv": "intermediate", "eq": "dumbbell", "cat": "strength", "pm": ["triceps"], "sm": [], "ins": ["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.", "Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.", "Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.", "Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.", "Repeat for the recommended amount of repetitions and switch arms."], "im": ["img/Dumbbell_One-Arm_Triceps_Extension_0.jpg", "img/Dumbbell_One-Arm_Triceps_Extension_1.jpg"]}, {"id": "Standing_Dumbbell_Triceps_Extension", "n": "Standing Dumbbell Triceps Extension", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["triceps"], "sm": [], "ins": ["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.", "The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.", "Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.", "Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.", "Repeat for the recommended amount of repetitions."], "im": ["img/Standing_Dumbbell_Triceps_Extension_0.jpg", "img/Standing_Dumbbell_Triceps_Extension_1.jpg"]}, {"id": "Cable_Rope_Overhead_Triceps_Extension", "n": "Cable Rope Overhead Triceps Extension", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["triceps"], "sm": [], "ins": ["Attach a rope to the bottom pulley of the pulley machine.", "Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.", "Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out.", "Repeat for the recommended amount of repetitions."], "im": ["img/Cable_Rope_Overhead_Triceps_Extension_0.jpg", "img/Cable_Rope_Overhead_Triceps_Extension_1.jpg"]}, {"id": "Ab_Roller", "n": "Ab Roller", "lv": "intermediate", "eq": "other", "cat": "strength", "pm": ["abdominals"], "sm": ["shoulders"], "ins": ["Hold the Ab Roller with both hands and kneel on the floor.", "Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.", "Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.", "After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."], "im": ["img/Ab_Roller_0.jpg", "img/Ab_Roller_1.jpg"]}, {"id": "Ab_Crunch_Machine", "n": "Ab Crunch Machine", "lv": "intermediate", "eq": "machine", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.", "At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.", "After a second pause, slowly return to the starting position as you breathe in.", "Repeat the movement for the prescribed amount of repetitions."], "im": ["img/Ab_Crunch_Machine_0.jpg", "img/Ab_Crunch_Machine_1.jpg"]}, {"id": "Reverse_Crunch", "n": "Reverse Crunch", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.", "Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.", "While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.", "Hold the contraction for a second and move your legs back to the starting position while exhaling.", "Repeat for the recommended amount of repetitions."], "im": ["img/Reverse_Crunch_0.jpg", "img/Reverse_Crunch_1.jpg"]}, {"id": "Sit-Up", "n": "Sit-Up", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.", "Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.", "Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."], "im": ["img/Sit-Up_0.jpg", "img/Sit-Up_1.jpg"]}, {"id": "Decline_Crunch", "n": "Decline Crunch", "lv": "intermediate", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Secure your legs at the end of the decline bench and lie down.", "Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.", "While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.", "Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.", "After the one second contraction, begin to come down slowly again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Decline_Crunch_0.jpg", "img/Decline_Crunch_1.jpg"]}, {"id": "Leg_Pull-In", "n": "Leg Pull-In", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["abdominals"], "sm": [], "ins": ["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.", "Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.", "Return to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Leg_Pull-In_0.jpg", "img/Leg_Pull-In_1.jpg"]}, {"id": "Seated_Barbell_Military_Press", "n": "Seated Barbell Military Press", "lv": "intermediate", "eq": "barbell", "cat": "strength", "pm": ["shoulders"], "sm": ["triceps"], "ins": ["Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.", "Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the collarbone slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."], "im": ["img/Seated_Barbell_Military_Press_0.jpg", "img/Seated_Barbell_Military_Press_1.jpg"]}, {"id": "Clean_and_Press", "n": "Clean and Press", "lv": "intermediate", "eq": "barbell", "cat": "strength", "pm": ["shoulders"], "sm": ["abdominals", "calves", "glutes", "hamstrings", "lower back", "middle back", "quadriceps", "shoulders", "traps", "triceps"], "ins": ["Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.", "Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.", "As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.", "At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.", "As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.", "Stand to full height, holding the bar in the clean position.", "Without moving your feet, press the bar overhead as you exhale. Lower the bar under control ."], "im": ["img/Clean_and_Press_0.jpg", "img/Clean_and_Press_1.jpg"]}, {"id": "Push_Press", "n": "Push Press", "lv": "expert", "eq": "barbell", "cat": "olympic weightlifting", "pm": ["shoulders"], "sm": ["quadriceps", "triceps"], "ins": [], "im": ["img/Push_Press_0.jpg", "img/Push_Press_1.jpg"]}, {"id": "Dumbbell_Rear_Lunge", "n": "Dumbbell Rear Lunge", "lv": "intermediate", "eq": "dumbbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.", "Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.", "Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.", "Now repeat with the opposite leg."], "im": ["img/Dumbbell_Rear_Lunge_0.jpg", "img/Dumbbell_Rear_Lunge_1.jpg"]}, {"id": "Barbell_Walking_Lunge", "n": "Barbell Walking Lunge", "lv": "beginner", "eq": "barbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Begin standing with your feet shoulder width apart and a barbell across your upper back.", "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "Step forward with your rear foot, repeating the lunge on the opposite leg."], "im": ["img/Barbell_Walking_Lunge_0.jpg", "img/Barbell_Walking_Lunge_1.jpg"]}, {"id": "Standing_Leg_Curl", "n": "Standing Leg Curl", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["hamstrings"], "sm": [], "ins": ["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.", "Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.", "As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.", "Perform the same exercise now for the left leg."], "im": ["img/Standing_Leg_Curl_0.jpg", "img/Standing_Leg_Curl_1.jpg"]}, {"id": "Thigh_Abductor", "n": "Thigh Abductor", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["abductors"], "sm": ["glutes"], "ins": ["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them away from each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."], "im": ["img/Thigh_Abductor_0.jpg", "img/Thigh_Abductor_1.jpg"]}, {"id": "Thigh_Adductor", "n": "Thigh Adductor", "lv": "beginner", "eq": "machine", "cat": "strength", "pm": ["adductors"], "sm": ["glutes", "hamstrings"], "ins": ["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them towards each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."], "im": ["img/Thigh_Adductor_0.jpg", "img/Thigh_Adductor_1.jpg"]}, {"id": "Cable_Hip_Adduction", "n": "Cable Hip Adduction", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["quadriceps"], "sm": [], "ins": ["Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.", "Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.", "Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.", "Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.", "Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg."], "im": ["img/Cable_Hip_Adduction_0.jpg", "img/Cable_Hip_Adduction_1.jpg"]}, {"id": "Glute_Kickback", "n": "Glute Kickback", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["glutes"], "sm": ["hamstrings"], "ins": ["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.", "As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.", "Go back to the initial position as you inhale and now repeat with the left leg.", "Continue to alternate legs until all of the recommended repetitions have been performed."], "im": ["img/Glute_Kickback_0.jpg", "img/Glute_Kickback_1.jpg"]}, {"id": "Donkey_Calf_Raises", "n": "Donkey Calf Raises", "lv": "intermediate", "eq": "other", "cat": "strength", "pm": ["calves"], "sm": [], "ins": ["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.", "Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.", "Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."], "im": ["img/Donkey_Calf_Raises_0.jpg", "img/Donkey_Calf_Raises_1.jpg"]}, {"id": "Farmers_Walk", "n": "Farmer's Walk", "lv": "intermediate", "eq": "other", "cat": "strongman", "pm": ["forearms"], "sm": ["abdominals", "glutes", "hamstrings", "lower back", "quadriceps", "traps"], "ins": ["There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren't available. Begin by standing between the implements.", "After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.", "Walk taking short, quick steps, and don't forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible."], "im": ["img/Farmers_Walk_0.jpg", "img/Farmers_Walk_1.jpg"]}, {"id": "Pullups", "n": "Pullups", "lv": "beginner", "eq": "body only", "cat": "strength", "pm": ["lats"], "sm": ["biceps", "middle back"], "ins": ["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."], "im": ["img/Pullups_0.jpg", "img/Pullups_1.jpg"]}, {"id": "EZ-Bar_Skullcrusher", "n": "EZ-Bar Skullcrusher", "lv": "beginner", "eq": "e-z curl bar", "cat": "strength", "pm": ["triceps"], "sm": ["forearms"], "ins": ["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.", "Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.", "Lift the bar back to the starting position by extending the elbow and exhaling.", "Repeat."], "im": ["img/EZ-Bar_Skullcrusher_0.jpg", "img/EZ-Bar_Skullcrusher_1.jpg"]}, {"id": "Dips_-_Chest_Version", "n": "Dips - Chest Version", "lv": "intermediate", "eq": "other", "cat": "strength", "pm": ["chest"], "sm": ["shoulders", "triceps"], "ins": ["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.", "While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.", "Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.", "Repeat the movement for the prescribed amount of repetitions."], "im": ["img/Dips_-_Chest_Version_0.jpg", "img/Dips_-_Chest_Version_1.jpg"]}, {"id": "Split_Squat_with_Dumbbells", "n": "Split Squat with Dumbbells", "lv": "beginner", "eq": "dumbbell", "cat": "strength", "pm": ["quadriceps"], "sm": ["glutes", "hamstrings"], "ins": ["Position yourself into a staggered stance with the rear foot elevated and front foot forward.", "Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.", "Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.", "At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."], "im": ["img/Split_Squat_with_Dumbbells_0.jpg", "img/Split_Squat_with_Dumbbells_1.jpg"]}, {"id": "Pull_Through", "n": "Pull Through", "lv": "beginner", "eq": "cable", "cat": "strength", "pm": ["glutes"], "sm": ["hamstrings", "lower back"], "ins": ["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.", "Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."], "im": ["img/Pull_Through_0.jpg", "img/Pull_Through_1.jpg"]}, {"id": "Bench_Jump", "n": "Bench Jump", "lv": "intermediate", "eq": "body only", "cat": "plyometrics", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.", "Perform a short squat in preparation for the jump; swing your arms behind you.", "Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.", "Jump over the bench, landing with the knees bent, absorbing the impact through the legs.", "Turn around and face the opposite direction, then jump back over the bench."], "im": ["img/Bench_Jump_0.jpg", "img/Bench_Jump_1.jpg"]}, {"id": "Freehand_Jump_Squat", "n": "Freehand Jump Squat", "lv": "intermediate", "eq": "body only", "cat": "strength", "pm": ["quadriceps"], "sm": ["calves", "glutes", "hamstrings"], "ins": ["Cross your arms over your chest.", "With your head up and your back straight, position your feet at shoulder width.", "Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.", "Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.", "When you touch the floor again, immediately squat down and jump again.", "Repeat for the recommended amount of repetitions."], "im": ["img/Freehand_Jump_Squat_0.jpg", "img/Freehand_Jump_Squat_1.jpg"]}];
